const c=window.LAUNCH_CONFIG;document.documentElement.style.setProperty('--accent',c.accent);document.querySelectorAll('[data-name]').forEach(el=>el.textContent=c.name);document.querySelectorAll('[data-tag]').forEach(el=>el.textContent=c.tagline);document.querySelector('[data-bio]').textContent=c.bio;document.querySelector('[data-contact]').href='mailto:'+encodeURIComponent(c.email);document.querySelector('[data-contact]').textContent=c.email;const grid=document.querySelector('[data-cards]');for(const row of c.entries){const card=document.createElement('article');card.className='card';const label=document.createElement('span');label.textContent=row.label;const h=document.createElement('h3');h.textContent=row.title;const p=document.createElement('p');p.textContent=row.text;card.append(label,h,p);grid.append(card)}